int main(){FVM_Config cfg;FVM_Runtime *rt=0;FVM_Context *c=0;FVM_Object *sub=0,*super=0,*old=0,*parent=0;assert(fvm_config_init(&cfg)==FVM_OK && fvm_runtime_create(&cfg,&rt)==FVM_OK && fvm_context_create(rt,&c)==FVM_OK);unsigned char swf[]={'F','W','S',8,16,0,0,0,8,0,0,12,1,0,0,0};assert(fvm_load_memory(c,swf,sizeof(swf))==FVM_OK && fvm_standard_install(c)==FVM_OK && fvm_object_create(c,&sub)==FVM_OK && fvm_gc_pin(c,sub)==FVM_OK && fvm_object_create(c,&super)==FVM_OK && fvm_gc_pin(c,super)==FVM_OK && fvm_object_create(c,&old)==FVM_OK && fvm_object_create(c,&parent)==FVM_OK);FVM_Value a,b,value,out;fvm_value_undefined(&a);a.type=FVM_VALUE_OBJECT;a.object=sub;b=a;b.object=super;value=a;value.object=old;assert(fvm_object_set(c,sub,"prototype",&value)==FVM_OK);value.object=parent;assert(fvm_object_set(c,super,"prototype",&value)==FVM_OK);bool success=false;unsigned failures=0;for(long boundary=0;boundary<2000 && !success;++boundary){FVM_GCRootFrame *roots=c->gc_frames;allowance=boundary;FVM_Result r=fvm_exec_extends(c,&a,&b);allowance=-1;assert(c->gc_frames==roots && fvm_object_get(c,sub,"prototype",&out)==FVM_OK);if(r==FVM_OK){assert(out.object!=old && out.object->prototype==parent);success=true;}else{assert(r==FVM_OUT_OF_MEMORY && out.object==old);++failures;}assert(fvm_gc_collect(c,0)==FVM_OK);}assert(success && failures);fvm_context_destroy(c);fvm_runtime_destroy(rt);return 0;}
